document.addEventListener('click', function (e) {
	var card = e.target.closest && e.target.closest(".e-loop-item.elementor-327,.e-loop-item.product_tag-upcoming");
	if (!card || e.defaultPrevented || e.button !== 0) return;
	// Sold out (vino-sales-state.php): the card no longer leads to the sales page.
	if (card.classList.contains('vino-sales-soldout')) return;
	if (e.target.closest('a, button, input, select, textarea, .swiper-button-next, .swiper-button-prev, .swiper-pagination')) return;
	var link = card.querySelector('a[href]');
	if (!link) return;
	if (e.ctrlKey || e.metaKey || e.shiftKey) { window.open(link.href, '_blank'); return; }
	window.location.href = link.href;
});

(function(){
  try {
    if (!window.Bil24ForceRebuild) {
      window.Bil24ForceRebuild = function(){
        try {
          if (window.Bil24Picker && window.jQuery) {
            var $ = window.jQuery;
            var $cat = $('#bil24-category');
            if (!$cat.length) return;
            var m = Bil24Picker.matrix || { categories: [] };
            var prev = $cat.val();
            $cat.empty().append($('', {
              value: '',
              text: (Bil24Picker.i18n && Bil24Picker.i18n.chooseCategory) || '— выберите категорию —',
              disabled: true,
              selected: true
            }));

            (m.categories || []).forEach(function(mc){
              var text = mc.name;
              var currency = (Bil24Picker.currency || '');

              if (mc.tariffs && mc.tariffs.length) {
                var minP = null, maxP = null;
                for (var tj = 0; tj < mc.tariffs.length; tj++) {
                  var tv = mc.tariffs[tj] || {};
                  var pv = tv.price;
                  if (pv !== '' && pv !== null && !isNaN(pv)) {
                    pv = parseFloat(pv);
                    if (minP === null || pv < minP) minP = pv;
                    if (maxP === null || pv > maxP) maxP = pv;
                  }
                }
                if (minP !== null) {
                  text = mc.name + ' — ' + String(minP);
                  if (maxP !== null && maxP !== minP) text += '–' + String(maxP);
                  text += ' ' + currency;
                }
              } else if (mc.price !== '' && mc.price !== null && !isNaN(mc.price)) {
                text = mc.name + ' — ' + mc.price + ' ' + currency;
              }

              $cat.append($('', {
                value: String(mc.id),
                text: text,
                'data-name': mc.name,
                'data-availability': (mc.availability || ''),
                'data-has-tariffs': (mc.tariffs && mc.tariffs.length) ? 1 : 0
              }));
            });

            if (prev) $cat.val(prev);
          }
        } catch (e) {}
      };

      setTimeout(function(){
        try {
          var have = document.querySelectorAll('#bil24-category option').length - 1;
          var matLen = (window.Bil24Picker && Bil24Picker.matrix && Array.isArray(Bil24Picker.matrix.categories))
            ? Bil24Picker.matrix.categories.length
            : 0;
          var exp = Math.min(20, matLen);
          if (exp > 0 && have > 0 && have < exp) {
            window.Bil24ForceRebuild();
          }
        } catch (e) {}
      }, 300);
    }
  } catch (e) {}
}).call(this);

(function() {
	'use strict';
	var parentSelector = '.menu-item.wpml-ls-current-language.menu-item-has-children';

	function toggleSubmenu(link, forceClose) {
		var isExpanded = link.getAttribute('aria-expanded') === 'true';
		if (forceClose || isExpanded) {
			link.setAttribute('aria-expanded', 'false');
		} else {
			link.setAttribute('aria-expanded', 'true');
		}
	}

	function handleKeydown(e) {
		var key = e.key || e.keyCode;
		if (key === 'Enter' || key === ' ' || key === 13 || key === 32) {
			e.preventDefault();
			toggleSubmenu(this);
		} else if (key === 'Escape' || key === 'Esc' || key === 27) {
			if (this.getAttribute('aria-expanded') === 'true') {
				e.preventDefault();
				toggleSubmenu(this, true);
			}
		}
	}

	function handleBlur(e) {
		var link = this;
		var parent = link.closest(parentSelector);
		if (!parent) return;

		setTimeout(function() {
			if (!parent.contains(document.activeElement)) {
				toggleSubmenu(link, true);
			}
		}, 100);
	}

	function init() {
		var parents = document.querySelectorAll(parentSelector);
		for (var i = 0; i < parents.length; i++) {
			var link = parents[i].querySelector('a[aria-expanded]');
			if (link) {
				link.addEventListener('keydown', handleKeydown);
				link.addEventListener('blur', handleBlur);
			}
		}
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}
})();
